import json

def serialize_model(architecture, weights, filepath):
    # already covered as weights and architecture together in this topic
    model_data = {
        "architecture": architecture,
        "weights": weights,
        "framework_version": "1.0.0",  # already covered as version compatibility risks in this topic
    }
    with open(filepath, "w") as f:
        json.dump(model_data, f)
    return model_data

def load_model(filepath):
    # already covered as serialization versus checkpointing in this topic
    with open(filepath) as f:
        return json.load(f)

architecture = {"layers": [4, 8, 4, 1], "activation": "relu"}
weights = {"layer_1": [0.1, 0.2, -0.3, 0.5], "layer_2": [0.4, -0.1]}

saved_model = serialize_model(architecture, weights, "/tmp/model.json")
print(f"Serialized model (already covered in this topic): {saved_model}")

loaded_model = load_model("/tmp/model.json")
print(f"\nLoaded model matches original: {loaded_model == saved_model}")
